import {t,getLocale} from './locales.js';import {goatInsight} from './goat-insights.js';import {goatOrdinal} from './goat-layout.js';
let whyOpen=false,labOpen=false;
/** Optional read-only explanation; it cannot grant, buy or advance time. @param {import('./engine.js').State} state @param {HTMLElement} host */
export function renderGoatLab(state,host){const g=state.goat;if(!g?.visited)return;const snapshot=goatInsight(state),n=(/** @type {number} */v)=>new Intl.NumberFormat(getLocale(),{maximumFractionDigits:2}).format(v),why=document.createElement('details');why.id='goat-why';why.open=whyOpen;why.addEventListener('toggle',()=>{whyOpen=why.open;});const title=document.createElement('summary');title.dataset.goatAction='why';title.textContent=t('goatWhy');const copy=document.createElement('p');copy.textContent=snapshot.welfare?.reasons.map(t).join(' ')+' '+t('goatGrowthCause')+' '+t('goatModelInfo');why.append(title,copy);const lab=document.createElement('details');lab.id='goat-lab';lab.open=labOpen;lab.addEventListener('toggle',()=>{labOpen=lab.open;});const heading=document.createElement('summary');heading.dataset.goatAction='lab';heading.textContent=t('goatLab');lab.append(heading);
 /** @param {string} key @param {string} value */
 const line=(key,value)=>{const p=document.createElement('p');p.textContent=t(key)+': '+value;lab.append(p);};
 line('goatCareFactors',t('goatNutrition')+' '+Math.round(g.nutrition*100)+'% · '+t('goatHydration')+' '+Math.round(g.hydration*100)+'% · '+t('goatComfort')+' '+Math.round((snapshot.welfare?.score||0)*100)+'%');line('goatModelTerms','0.32 × '+t('goatNutrition')+' + 0.32 × '+t('goatHydration')+' + 0.22 × '+t('goatShelter')+' + 0.14 × '+t('goatSpaceFactor')+' − '+n(snapshot.welfare?.weatherPenalty||0));line('goatActualUse',n(g.stats.hayUsedG/1000)+' kg hay · '+n(g.stats.browseUsedG/1000)+' kg '+t('goatPastureBiomass')+' · '+n(g.stats.waterUsedMl/1000)+' L');line('goatRanchPL',t('goatRevenue')+' '+n(snapshot.economics.revenue)+' · '+t('goatCosts')+' '+n(snapshot.economics.costs)+' · '+t('goatNet')+' '+n(snapshot.economics.net)+' Coins');line('goatAccountingNote',t('goatAccountingDetail'));
 for(const sale of snapshot.economics.sales)line(t('goatSold')+' '+goatOrdinal(sale.id),t('goatRevenue')+' '+sale.price+' · '+t('goatAllocatedCost')+' '+n(sale.allocatedCost)+' · '+t('goatAllocatedNet')+' '+n(sale.allocatedNet));
 for(const quote of snapshot.quotes.filter(q=>q.price))line(t('goatViewQuote')+' '+goatOrdinal(quote.id),'130 + '+n(quote.conditionValue)+' + '+quote.dayBonus+' → '+quote.price+' Coins');
 const trends=document.createElement('p');trends.textContent=t('goatTrends');lab.append(trends);if(!snapshot.history.length)line('goatNoHistory',t('goatHistoryCadence'));else{const list=document.createElement('ol');list.className='goat-trends';for(const h of snapshot.history.slice(-12)){const li=document.createElement('li');li.textContent='h '+h.tick+' · '+t('goatGrowth')+' '+Math.round(h.growth*100)+'% · '+t('goatNutrition')+' '+Math.round(h.nutrition*100)+'% · '+t('goatHydration')+' '+Math.round(h.hydration*100)+'% · '+n(h.hayUsedG/1000)+' kg hay · '+n(h.browseUsedG/1000)+' kg '+t('goatPastureBiomass')+' · '+n(h.waterUsedMl/1000)+' L · '+t('goatNet')+' '+h.profit;list.append(li);}lab.append(list);}why.append(lab);host.append(why);}
